BEGIN;
CREATE TABLE IF NOT EXISTS verifier_tool_qualification (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, project_id uuid NOT NULL, goal_id uuid NOT NULL, revision_set_id text NOT NULL, tool_identity text NOT NULL, tool_digest text NOT NULL, qualification_level text NOT NULL, operational_requirements jsonb NOT NULL, validation_corpus_hash text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS proof_artifact (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, project_id uuid NOT NULL, goal_id uuid NOT NULL, revision_set_id text NOT NULL, claim jsonb NOT NULL, proof_hash text NOT NULL, checker_digest text NOT NULL, assumptions jsonb NOT NULL, tcb jsonb NOT NULL, replay_status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attestation_appraisal (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, project_id uuid NOT NULL, goal_id uuid NOT NULL, revision_set_id text NOT NULL, evidence_hash text NOT NULL, verifier_identity text NOT NULL, policy_digest text NOT NULL, appraisal_result jsonb NOT NULL, freshness_at timestamptz NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE verifier_tool_qualification ENABLE ROW LEVEL SECURITY; ALTER TABLE proof_artifact ENABLE ROW LEVEL SECURITY; ALTER TABLE attestation_appraisal ENABLE ROW LEVEL SECURITY;
COMMIT;
